using System;using System.IO;using System.Collections.Generic;using System.Reflection;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad] public static class UsabilityAuditV07 {
  const string Key="ZTM_USABILITY_AUDIT_V07";static GameView view;static RenderTexture target;static int phase,size,warm,frame0;static double started;static StringBuilder log=new StringBuilder();
  static readonly int[] Widths={360,360,480},Heights={640,800,960};
  static string Root=>Directory.GetParent(Application.dataPath).FullName;static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
  static UsabilityAuditV07(){EditorApplication.update+=Tick;}
  public static string Start(){if(EditorApplication.isPlaying)throw new Exception("Editor busy");phase=size=warm=frame0=0;view=null;started=0;log.Clear();Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","v07-before-ui","save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();return "baseline audit queued; private profile; no production edits";}
  static string Focused=>(UI.panel.focusController.focusedElement as VisualElement)?.name??"<none>";
  static bool Warm(){return ++warm>20;}
  static void At(int p){phase=p;warm=0;}
  static PlayerState Fixture(){var s=new PlayerState{cash=59,freeSpins=0};s.fragments[0]=19;s.tutorial.completed=true;return s;}
  static void Target(){if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);}target=new RenderTexture(Widths[size],Heights[size],0,RenderTextureFormat.ARGB32);target.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=target;}
  static void Capture(string label,bool crop=false){var old=RenderTexture.active;RenderTexture.active=target;var t=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,target.width,target.height),0,0);t.Apply();string n="v07-before-"+label+"-"+target.width+"x"+target.height+".png";File.WriteAllBytes(Path.Combine(Root,"Evidence",n),t.EncodeToPNG());if(crop){var r=UI.Q<Button>("spin").worldBound;float scale=target.width/UI.worldBound.width;int x=Mathf.RoundToInt(r.x*scale),y=Mathf.RoundToInt(target.height-r.yMax*scale),w=Mathf.RoundToInt(r.width*scale),h=Mathf.RoundToInt(r.height*scale);var cut=new Texture2D(w,h,TextureFormat.RGBA32,false);cut.SetPixels(t.GetPixels(x,y,w,h));cut.Apply();File.WriteAllBytes(Path.Combine(Root,"Evidence","v07-before-spin-"+label+"-"+target.width+"x"+target.height+".png"),cut.EncodeToPNG());UnityEngine.Object.Destroy(cut);}UnityEngine.Object.Destroy(t);RenderTexture.active=old;log.AppendLine("CAPTURE "+n+" frame="+Time.frameCount);}
  static void KeyEscape(){var e=new Event{type=EventType.KeyDown,keyCode=KeyCode.Escape};using(var k=KeyDownEvent.GetPooled(e)){k.target=(UI.panel.focusController.focusedElement as VisualElement)??UI;((VisualElement)k.target).SendEvent(k);}}
  static void Metrics(){var p=view.GetComponent<UIDocument>().panelSettings;log.AppendLine("SIZE "+target.width+"x"+target.height+" logical="+UI.worldBound+" scale="+p.scaleMode+" reference="+p.referenceResolution+" match="+p.match+" TextSettings="+(p.textSettings==null?"default/null":p.textSettings.name));
   foreach(var l in UI.Query<Label>().ToList()){if(l.resolvedStyle.display==DisplayStyle.None||l.worldBound.width<=0)continue;if(l.name=="quest-status"||l.name=="quest-title"||l.name=="cash-count"||l.name=="feedback-hint"||l.name=="fragment-count-0"){var m=l.MeasureTextSize(l.text,0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined);log.AppendLine("LABEL "+l.name+" text="+l.text+" font="+l.resolvedStyle.fontSize+" style="+l.resolvedStyle.unityFontStyleAndWeight+" measured="+m+" available="+l.contentRect);}}
   foreach(var b in UI.Query<Button>().ToList()){bool shown=true;for(VisualElement e=b;e!=null;e=e.parent)if(e.resolvedStyle.display==DisplayStyle.None)shown=false;if(shown)log.AppendLine("TARGET "+b.name+" bound="+b.worldBound+" enabled="+b.enabledInHierarchy+" tabIndex="+b.tabIndex+" focusable="+b.focusable);}
  }
  sealed class FailingStore:IStateStore{public PlayerState state;public bool Save(PlayerState s,out string error){error="Save failed: IOException";return false;}public PlayerState Load(out string notice){notice="";return new GameModel(state).Snapshot;}}
  static void FailureAudit(){var s=Fixture();s.cash=60;s.fragments[0]=20;view.SetQaState(s,0);var fail=new GameSession(new FailingStore{state=s},new SeededRandom(57));typeof(GameView).GetField("session",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(view,fail);view.QaBuy(0);view.QaClick("menu");var label=UI.Q<VisualElement>("settings")[1] as Label;log.AppendLine("SAVE_FAILURE error="+fail.Error+" notice="+fail.Notice+" menuLabel="+label.text+" cash="+view.Model.Snapshot.cash+" owned="+view.Model.PurchasedCount);}
  static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(started==0)started=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-started>150)throw new Exception("Audit timeout");if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;frame0=Time.frameCount;At(0);}
   if(phase==0){Target();view.SetQaState(Fixture(),0);At(1);}else if(phase==1&&Warm()){Metrics();view.enabled=false;UI.Q<Button>("spin").Blur();Capture("main",true);UI.Q<Button>("spin").Focus();At(2);}
   else if(phase==2&&Warm()){log.AppendLine("FOCUS spin requested; actual="+Focused);Capture("focused",true);view.QaClick("menu");At(3);}
   else if(phase==3&&Warm()){log.AppendLine("MODAL open focus="+Focused+" display="+UI.Q<VisualElement>("settings").resolvedStyle.display);Capture("menu");KeyEscape();At(4);}
   else if(phase==4&&Warm()){log.AppendLine("ESCAPE menu remains="+UI.Q<VisualElement>("settings").resolvedStyle.display);view.QaClick("close-settings");log.AppendLine("MODAL close focus="+Focused);view.QaClick("menu");view.QaClick("tutorial-replay");At(5);}
   else if(phase==5&&Warm()){Capture("dialogue");if(++size<3){view.enabled=true;At(0);}else{FailureAudit();At(6);}}
   else if(phase==6&&Warm()){Capture("save-failure-menu");log.AppendLine("ADVANCING frames="+(Time.frameCount-frame0)+"; synthetic UI/keyboard events, actual offscreen Editor pixels; no OS input");Finish();}
  }catch(Exception e){log.AppendLine("AUDIT ERROR "+e);Debug.LogException(e);Finish();}}
  static void Finish(){SessionState.SetBool(Key,false);File.WriteAllText(Path.Combine(Root,"Evidence","v07-before-usability-audit.txt"),log.ToString());if(view!=null)view.enabled=true;if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);target=null;}EditorApplication.ExitPlaymode();Debug.Log("ZTM_V07_BASELINE_COMPLETE");}
 }
}